        self.minutesTranscribed = minutesTranscribed
        self.estimatedUsd = estimatedUsd
        self.estimatedInr = estimatedInr
        self.projectedMonthlyUsd = projectedMonthlyUsd
        self.projectedMonthlyInr = projectedMonthlyInr
        self.localPercentage = localPercentage
        self.cloudPercentage = cloudPercentage
        self.capWarnings = capWarnings
    }
}



extension FfiCostDashboard: Equatable, Hashable {
    public static func ==(lhs: FfiCostDashboard, rhs: FfiCostDashboard) -> Bool {
        if lhs.minutesTranscribed != rhs.minutesTranscribed {
            return false
        }
        if lhs.estimatedUsd != rhs.estimatedUsd {
            return false
        }
        if lhs.estimatedInr != rhs.estimatedInr {
            return false
        }
        if lhs.projectedMonthlyUsd != rhs.projectedMonthlyUsd {
            return false
        }
        if lhs.projectedMonthlyInr != rhs.projectedMonthlyInr {
            return false
        }
        if lhs.localPercentage != rhs.localPercentage {
            return false
        }
        if lhs.cloudPercentage != rhs.cloudPercentage {
            return false
        }
        if lhs.capWarnings != rhs.capWarnings {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(minutesTranscribed)
        hasher.combine(estimatedUsd)
        hasher.combine(estimatedInr)
        hasher.combine(projectedMonthlyUsd)
        hasher.combine(projectedMonthlyInr)
