public struct FfiDictationResult {
    public var text: String
    public var uiState: FfiUiState
    public var latencyMs: UInt64
    public var success: Bool

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(text: String, uiState: FfiUiState, latencyMs: UInt64, success: Bool) {
        self.text = text
        self.uiState = uiState
        self.latencyMs = latencyMs
        self.success = success
    }
}



extension FfiDictationResult: Equatable, Hashable {
    public static func ==(lhs: FfiDictationResult, rhs: FfiDictationResult) -> Bool {
        if lhs.text != rhs.text {
            return false
        }
        if lhs.uiState != rhs.uiState {
            return false
        }
        if lhs.latencyMs != rhs.latencyMs {
            return false
        }
        if lhs.success != rhs.success {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(text)
        hasher.combine(uiState)
        hasher.combine(latencyMs)
        hasher.combine(success)
    }
}


