public enum FfiUiState {
    
    case idle
    case listening
    case cleaning
    case inserting
    case copied
    case done
    case error
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeFfiUiState: FfiConverterRustBuffer {
    typealias SwiftType = FfiUiState

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FfiUiState {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .idle
        
        case 2: return .listening
        
        case 3: return .cleaning
        
        case 4: return .inserting
        
        case 5: return .copied
        
        case 6: return .done
        
        case 7: return .error
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: FfiUiState, into buf: inout [UInt8]) {
        switch value {
        
        
        case .idle:
            writeInt(&buf, Int32(1))
        
        
        case .listening:
            writeInt(&buf, Int32(2))
        
        
        case .cleaning:
            writeInt(&buf, Int32(3))
        
        
        case .inserting:
            writeInt(&buf, Int32(4))
        
        
        case .copied:
            writeInt(&buf, Int32(5))
        
        
        case .done:
            writeInt(&buf, Int32(6))
        
        
        case .error:
            writeInt(&buf, Int32(7))
        
        }
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeFfiUiState_lift(_ buf: RustBuffer) throws -> FfiUiState {
